// Rules that travel with their cells in the editor: Ctrl/Cmd+C or X and Ctrl/Cmd+V
// (the clipboard events they fire) take the data validation and the conditional
// formats of the copied cells to the cells that are written. What the rule does
// there, one undo step, a cut, text from elsewhere, a read-only view, save and
// reopen. The workbook is generated by code and kept within columns A to D of the
// first rows, so that a phone shows it as well.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const num = (ref: string, value: number) => `<c r="${ref}"><v>${value}</v></c>`;
const str = (ref: string, text: string) => `<c r="${ref}" t="inlineStr"><is><t>${text}</t></is></c>`;
const dv = (attrs: string, inner = '') => `<dataValidation ${attrs}>${inner}</dataValidation>`;

const STYLES =
  '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="1"><font><sz val="11"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/></cellXfs><dxfs count="1"><dxf><fill><patternFill><bgColor rgb="FFFFC7CE"/></patternFill></fill></dxf></dxfs></styleSheet>';

let made: Promise<Uint8Array> | undefined;
/** "Data": A2:A9 whole numbers 1 to 10 (a value outside is stopped) and red above the cell beside it; B2:B3 a list. */
const workbook = () =>
  (made ??= buildXlsx({
    sheets: [
      {
        name: 'Data',
        xml: worksheetXml(
          `<sheetData><row r="1">${str('A1', 'Qty')}${str('B1', 'Answer')}</row><row r="2">${num('A2', 3)}${str('B2', 'Yes')}</row><row r="3">${num('A3', 7)}</row></sheetData>` +
            '<conditionalFormatting sqref="A2:A9"><cfRule type="cellIs" dxfId="0" priority="1" operator="greaterThan"><formula>B2</formula></cfRule></conditionalFormatting>' +
            '<dataValidations count="2">' +
            dv('type="whole" allowBlank="1" showErrorMessage="1" errorTitle="Quantity" error="Enter 1 to 10" sqref="A2:A9"', '<formula1>1</formula1><formula2>10</formula2>') +
            dv('type="list" allowBlank="1" showErrorMessage="1" sqref="B2:B3"', '<formula1>"Yes,No"</formula1>') +
            '</dataValidations>',
        ),
      },
      { name: 'Other', xml: worksheetXml('<sheetData/>') },
    ],
    styles: STYLES,
  }));

async function mount(page: Page, bytes: Uint8Array, options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/editor.html');
  await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, options, 'host');
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options } },
  );
}

const select = (page: Page, ref: string) =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    const view = (window as any).__editor.view;
    view.select(api.parseRange(ref));
    view.focus();
  }, ref);

interface Clip {
  text: string;
  html: string;
}

/** Fires a clipboard event at the input the way the browser does for Ctrl/Cmd+C, X and V, and returns what ended up on the clipboard. */
function clipboardEvent(page: Page, type: 'copy' | 'cut' | 'paste', give?: Clip | { text: string }): Promise<Clip> {
  return page.evaluate(
    ([type, text, html]) => {
      const data = new DataTransfer();
      if (text !== null) data.setData('text/plain', text);
      if (html !== null) data.setData('text/html', html);
      let event: Event | undefined;
      try {
        event = new ClipboardEvent(type, { clipboardData: data, bubbles: true, cancelable: true });
      } catch {
        event = undefined;
      }
      // Some browsers give a scripted clipboard event a clipboard of their own instead of the one passed in.
      if (!event || (event as ClipboardEvent).clipboardData !== data) {
        event = new Event(type, { bubbles: true, cancelable: true });
        Object.defineProperty(event, 'clipboardData', { value: data });
      }
      document.querySelector('#host .bym-input')!.dispatchEvent(event);
      return { text: data.getData('text/plain'), html: data.getData('text/html') };
    },
    [type, give ? give.text : null, give && 'html' in give ? give.html : null] as [string, string | null, string | null],
  );
}

/** Copies (or cuts) a range and pastes it at another: the two halves of Ctrl/Cmd+C and Ctrl/Cmd+V. */
async function copyTo(page: Page, from: string, to: string, cut = false): Promise<Clip> {
  await select(page, from);
  const clip = await clipboardEvent(page, cut ? 'cut' : 'copy');
  await select(page, to);
  await clipboardEvent(page, 'paste', clip);
  return clip;
}

async function typeIn(page: Page, ref: string, text: string): Promise<void> {
  await select(page, ref);
  await page.keyboard.type(text);
  await page.keyboard.press('Enter');
}

const cellValue = (page: Page, ref: string) =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    const at = api.parseCellRef(ref);
    const view = (window as any).__editor.view;
    const found = api.getCell(view.workbook.sheets[view.activeSheet], at.row, at.col);
    return found ? found.value : null;
  }, ref);

/** The rule of a cell as the view applies it: "ranges|type|formula1|formula2", or null. */
const ruleAt = (page: Page, ref: string) =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    const at = api.parseCellRef(ref);
    const rule = (window as any).__editor.view.validationAt(at.row, at.col);
    return rule ? `${rule.ranges.map(api.rangeName).join(' ')}|${rule.type}|${rule.formula1 ?? ''}|${rule.formula2 ?? ''}` : null;
  }, ref);

/** The conditional rules of the shown sheet as the view lists them: "ranges|type|formulas". */
const formats = (page: Page) =>
  page.evaluate(() => {
    const api = (window as any).BymOffice;
    return (window as any).__editor.view.conditionalRules().map((info: any) => `${info.ranges.map(api.rangeName).join(' ')}|${info.rule.type}|${info.rule.formulas.join(';')}`) as string[];
  });

const view = <T>(page: Page, code: string) => page.evaluate((code) => new Function('view', 'api', `return ${code}`)((window as any).__editor.view, (window as any).BymOffice), code) as Promise<T>;
const editing = (page: Page) => view<boolean>(page, 'view.isEditing');
const changes = (page: Page) => page.evaluate(() => (window as any).__events.filter((event: { type: string }) => event.type === 'change').length as number);
const notices = (page: Page) => page.evaluate(() => (window as any).__events.filter((event: { type: string }) => event.type === 'notice').map((event: { message: string }) => event.message) as string[]);

test.describe('rules go with copied cells', () => {
  test('a pasted cell has the validation of the cell it is a copy of: a value the rule stops is refused there, and one undo takes cell and rule away', async ({ page }) => {
    await mount(page, await workbook());
    expect(await ruleAt(page, 'C4')).toBeNull();
    await copyTo(page, 'A2', 'C4');
    expect(await cellValue(page, 'C4')).toBe(3);
    // The rule of column A has the cell as well: no second rule says the same.
    expect(await ruleAt(page, 'C4')).toBe('A2:A9 C4|whole|1|10');
    expect(await changes(page)).toBe(1);

    // It works at once: 99 is refused with the editor left open, 8 is written.
    await typeIn(page, 'C4', '99');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    expect(await cellValue(page, 'C4')).toBe(3);
    await typeIn(page, 'C4', '8');
    expect(await cellValue(page, 'C4')).toBe(8);

    // The 8 is one step, the paste with its rules another.
    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    expect(await cellValue(page, 'C4')).toBeNull();
    expect(await ruleAt(page, 'C4')).toBeNull();
    expect(await ruleAt(page, 'A2')).toBe('A2:A9|whole|1|10');
    expect(await view(page, 'view.undo()')).toBe(false);
    await view(page, 'view.redo()');
    expect(await ruleAt(page, 'C4')).toBe('A2:A9 C4|whole|1|10');
  });

  test('the conditional format comes along and is in the list of rules, with its formula for the new cells; undo takes it out', async ({ page }) => {
    await mount(page, await workbook());
    expect(await formats(page)).toEqual(['A2:A9|cellIs|B2']);
    await copyTo(page, 'A2:A3', 'C5');
    // One rule for both places: seen from C5 it compares with D5, as it compares A2 with B2.
    expect(await formats(page)).toEqual(['A2:A9 C5:C6|cellIs|B2']);
    expect(await view(page, 'view.conditionalRules(api.parseRange("C6")).length')).toBe(1);
    expect(await ruleAt(page, 'C6')).toBe('A2:A9 C5:C6|whole|1|10');
    // A block repeated over a selection twice its height takes the rules to both repeats.
    await select(page, 'A2');
    const clip = await clipboardEvent(page, 'copy');
    await select(page, 'D2:D3');
    await clipboardEvent(page, 'paste', clip);
    expect(await formats(page)).toEqual(['A2:A9 C5:C6 D2:D3|cellIs|B2']);
    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    expect(await formats(page)).toEqual(['A2:A9|cellIs|B2']);
    expect(await ruleAt(page, 'C6')).toBeNull();
  });

  test('what is pasted over loses its own rules; text from elsewhere changes none', async ({ page }) => {
    await mount(page, await workbook());
    // Text that is no copy of this view: typed in, and the list of B3 stays.
    await select(page, 'B3');
    await clipboardEvent(page, 'paste', { text: 'No' });
    expect(await cellValue(page, 'B3')).toBe('No');
    expect(await ruleAt(page, 'B3')).toBe('B2:B3|list|"Yes,No"|');
    // The same text with HTML of another program: likewise.
    await clipboardEvent(page, 'paste', { text: 'Yes', html: '<table><tr><td>Yes</td></tr></table>' });
    expect(await ruleAt(page, 'B3')).toBe('B2:B3|list|"Yes,No"|');
    // A copied cell without a rule leaves the cell it is pasted to without one; A1 had none to begin with.
    await copyTo(page, 'A1', 'B3');
    expect(await cellValue(page, 'B3')).toBe('Qty');
    expect(await ruleAt(page, 'B3')).toBeNull();
    expect(await ruleAt(page, 'B2')).toBe('B2|list|"Yes,No"|');
    // A copied cell with another rule brings that one, and takes the conditional format of the cell away.
    await copyTo(page, 'B2', 'A9');
    expect(await ruleAt(page, 'A9')).toBe('B2 A9|list|"Yes,No"|');
    expect(await ruleAt(page, 'A8')).toBe('A2:A8|whole|1|10');
    expect(await formats(page)).toEqual(['A2:A8|cellIs|B2']);
    expect(await notices(page)).toEqual([]);
  });

  test('a cut takes the rules away with the cells, and the paste puts them where the cells go; another sheet works the same', async ({ page }) => {
    await mount(page, await workbook());
    await select(page, 'A2:A3');
    const clip = await clipboardEvent(page, 'cut');
    expect(await cellValue(page, 'A2')).toBeNull();
    expect(await ruleAt(page, 'A2')).toBeNull();
    expect(await ruleAt(page, 'A4')).toBe('A4:A9|whole|1|10');
    expect(await formats(page)).toEqual(['A4:A9|cellIs|B4']);
    expect(await changes(page)).toBe(1);
    // Onto the other sheet: the rules are rules of that sheet.
    await view(page, 'view.setActiveSheet(1)');
    await select(page, 'B2');
    await clipboardEvent(page, 'paste', clip);
    expect(await cellValue(page, 'B3')).toBe(7);
    expect(await ruleAt(page, 'B3')).toBe('B2:B3|whole|1|10');
    expect(await formats(page)).toEqual(['B2:B3|cellIs|C2']);
    await typeIn(page, 'B2', '50');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    // Undone twice, everything is where it was.
    await view(page, 'view.undo()');
    expect(await view(page, 'view.workbook.sheets[1].dataValidations === undefined && view.workbook.sheets[1].conditionalFormats === undefined')).toBe(true);
    await view(page, 'view.undo()');
    await view(page, 'view.setActiveSheet(0)');
    expect(await ruleAt(page, 'A2')).toBe('A2:A9|whole|1|10');
    expect(await formats(page)).toEqual(['A2:A9|cellIs|B2']);
    expect(await cellValue(page, 'A2')).toBe(3);
  });

  test('saved and opened again, the pasted rules are in the file; pasted where it came from, a copy changes no rule of the file', async ({ page }) => {
    const bytes = await workbook();
    await mount(page, bytes);
    const read = () =>
      page.evaluate(async () => {
        const api = (window as any).BymOffice;
        const out = (await (window as any).__file.save()) as Uint8Array;
        const text = new TextDecoder().decode(await api.ZipArchive.read(out).read('xl/worksheets/sheet1.xml'));
        const book = await (await api.open(out)).workbook();
        return {
          xml: (text.match(/<conditionalFormatting[\s\S]*<\/dataValidations>/) || [''])[0],
          validations: book.sheets[0].dataValidations.map((rule: any) => `${rule.ranges.map(api.rangeName).join(' ')}|${rule.type}`),
          formats: book.sheets[0].conditionalFormats.map((format: any) => `${format.ranges.map(api.rangeName).join(' ')}|${format.rules.map((rule: any) => rule.formulas.join(';')).join(',')}`),
        };
      });
    // In place: the cells are written again, the rules are the text they were.
    await copyTo(page, 'A2:B3', 'A2');
    const same = await read();
    const original = new TextDecoder().decode(
      new Uint8Array(await page.evaluate(async (input) => Array.from(await (window as any).BymOffice.ZipArchive.read(new Uint8Array(input)).read('xl/worksheets/sheet1.xml')) as number[], Array.from(bytes))),
    );
    expect(same.xml).toBe((original.match(/<conditionalFormatting[\s\S]*<\/dataValidations>/) || [''])[0]);
    expect(same.xml).not.toBe('');
    // Elsewhere: the file has the rules where the view has them.
    await copyTo(page, 'A2:B3', 'C6');
    const saved = await read();
    expect(saved.validations).toEqual(['A2:A9 C6:C7|whole', 'B2:B3 D6:D7|list']);
    expect(saved.formats).toEqual(['A2:A9 C6:C7|B2']);
  });

  test('a validation the extension list of the file holds stays where it is, and the paste says that it did not come along', async ({ page }) => {
    const x14 =
      '<extLst><ext uri="{CCE6A557-97BC-4b89-ADB6-D9C93CAAB3DF}" xmlns:x14="http://schemas.microsoft.com/office/spreadsheetml/2009/9/main"><x14:dataValidations xmlns:xm="http://schemas.microsoft.com/office/excel/2006/main" count="1">' +
      '<x14:dataValidation type="list" allowBlank="1"><x14:formula1><xm:f>Lists!$A$1:$A$2</xm:f></x14:formula1><xm:sqref>B2:B3</xm:sqref></x14:dataValidation></x14:dataValidations></ext></extLst>';
    const bytes = await buildXlsx({
      sheets: [
        { name: 'Data', xml: worksheetXml(`<sheetData><row r="2">${num('A2', 3)}${str('B2', 'Red')}</row></sheetData><dataValidations count="1">${dv('type="whole" sqref="A2:A3"', '<formula1>1</formula1><formula2>10</formula2>')}</dataValidations>${x14}`) },
        { name: 'Lists', xml: worksheetXml(`<sheetData><row r="1">${str('A1', 'Red')}</row><row r="2">${str('A2', 'Blue')}</row></sheetData>`) },
      ],
    });
    await mount(page, bytes);
    expect(await ruleAt(page, 'B2')).toBe('B2:B3|list|Lists!$A$1:$A$2|');
    // Copied: the cell is pasted, its rule is not, and that is said.
    await copyTo(page, 'B2', 'D5');
    expect(await cellValue(page, 'D5')).toBe('Red');
    expect(await ruleAt(page, 'D5')).toBeNull();
    await expect.poll(() => notices(page)).toEqual(['One data validation or conditional format could not be pasted as it is where the cells come from: it is of a kind that is kept as the file has it']);
    // Pasted over: its cells keep it.
    await copyTo(page, 'A2', 'B3');
    expect(await cellValue(page, 'B3')).toBe(3);
    expect(await ruleAt(page, 'B3')).toBe('B2:B3|list|Lists!$A$1:$A$2|');
    await expect.poll(async () => (await notices(page)).length).toBe(2);
  });

  test('an empty cell with a list to choose from is copied and pasted with its rule, though the clipboard holds no text for it', async ({ page }) => {
    await mount(page, await workbook());
    // B3 is empty and has the list of B2:B3: the copy is no text at all, and the mark of the copy is in the HTML.
    await select(page, 'B3');
    const clip = await clipboardEvent(page, 'copy');
    expect(clip.text).toBe('');
    expect(clip.html).toContain('data-bym-copy=');
    await select(page, 'D5');
    await clipboardEvent(page, 'paste', clip);
    expect(await ruleAt(page, 'D5')).toBe('B2:B3 D5|list|"Yes,No"|');
    expect(await cellValue(page, 'D5')).toBeNull();
    expect(await changes(page)).toBe(1);
    // The list is there to choose from: a value that is not in it is stopped.
    await typeIn(page, 'D5', 'Maybe');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    await view(page, 'view.undo()');
    expect(await ruleAt(page, 'D5')).toBeNull();
    // No text from elsewhere is nothing to paste, as it was; neither is an empty copy that has no rule and no note.
    await select(page, 'A2');
    await clipboardEvent(page, 'paste', { text: '' });
    await clipboardEvent(page, 'paste', { text: '', html: '<table><tr><td></td></tr></table>' });
    expect(await cellValue(page, 'A2')).toBe(3);
    await select(page, 'D8');
    const bare = await clipboardEvent(page, 'copy');
    await select(page, 'A2');
    await clipboardEvent(page, 'paste', bare);
    expect(await cellValue(page, 'A2')).toBe(3);
    expect(await ruleAt(page, 'A2')).toBe('A2:A9|whole|1|10');
    expect(await changes(page)).toBe(2);
  });

  test('Paste from the menu takes the HTML of the clipboard where the browser hands it out: a cut made in this view arrives with its rules', async ({ page }) => {
    await mount(page, await workbook());
    await select(page, 'A2:A3');
    const clip = await clipboardEvent(page, 'cut');
    expect(await ruleAt(page, 'A2')).toBeNull();
    // The clipboard of the system as the menu reads it: the kinds of content it holds, each to be asked for.
    await page.evaluate((content) => {
      const item = { types: ['text/plain', 'text/html'], getType: (type: string) => Promise.resolve(new Blob([type === 'text/html' ? content.html : content.text], { type })) };
      Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { read: () => Promise.resolve([item]), readText: () => Promise.resolve(content.text), writeText: () => Promise.resolve() } });
    }, clip);
    const openMenuAt = async (row: number, col: number) => {
      const box = (await page.locator('#host .bym-canvas').boundingBox())!;
      // A point inside a cell of an unscrolled sheet with default sizes.
      const point = { x: box.x + 72 + 64 * (col + 0.5), y: box.y + 22 + 20 * (row + 0.5) };
      await page.evaluate(([x, y]) => void document.querySelector('#host .bym-canvas')!.dispatchEvent(new MouseEvent('contextmenu', { clientX: x, clientY: y, button: 2, bubbles: true, cancelable: true })), [point.x, point.y]);
      await expect(page.locator('#host .bym-menu')).toBeVisible();
    };
    await openMenuAt(4, 2);
    expect(await view(page, 'api.rangeName(view.selection.range)')).toBe('C5');
    await page.locator('#host .bym-menu button', { hasText: /^Paste$/ }).click();
    await expect.poll(() => ruleAt(page, 'C6')).toBe('A4:A9 C5:C6|whole|1|10');
    expect(await cellValue(page, 'C6')).toBe(7);
    expect(await formats(page)).toEqual(['A4:A9 C5:C6|cellIs|B4']);

    // A browser that only hands out the text: the cells come as text, and the rules that were cut are not brought.
    await view(page, 'view.undo()');
    await page.evaluate((content) => Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { readText: () => Promise.resolve(content.text), writeText: () => Promise.resolve() } }), clip);
    await openMenuAt(4, 2);
    await page.locator('#host .bym-menu button', { hasText: /^Paste$/ }).click();
    await expect.poll(() => cellValue(page, 'C6')).toBe(7);
    expect(await ruleAt(page, 'C6')).toBeNull();
    // Refused by the browser or the user: said once, and not asked a second time.
    await page.evaluate(() => {
      (window as any).__asked = 0;
      const refuse = () => {
        (window as any).__asked++;
        return Promise.reject(new DOMException('denied', 'NotAllowedError'));
      };
      Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { read: refuse, readText: refuse, writeText: () => Promise.resolve() } });
    });
    await openMenuAt(6, 2);
    await page.locator('#host .bym-menu button', { hasText: /^Paste$/ }).click();
    await expect.poll(() => notices(page)).toEqual(['The clipboard cannot be read here. Press Ctrl+V to paste.']);
    expect(await page.evaluate(() => (window as any).__asked)).toBe(1);
  });

  test('notes and rules that could not go with the cells are both said', async ({ page }) => {
    const x14 =
      '<extLst><ext uri="{CCE6A557-97BC-4b89-ADB6-D9C93CAAB3DF}" xmlns:x14="http://schemas.microsoft.com/office/spreadsheetml/2009/9/main"><x14:dataValidations xmlns:xm="http://schemas.microsoft.com/office/excel/2006/main" count="1">' +
      '<x14:dataValidation type="list" allowBlank="1"><x14:formula1><xm:f>Lists!$A$1:$A$2</xm:f></x14:formula1><xm:sqref>B2:B3</xm:sqref></x14:dataValidation></x14:dataValidations></ext></extLst>';
    const bytes = await buildXlsx({
      sheets: [
        { name: 'Data', xml: worksheetXml(`<sheetData><row r="2">${str('B2', 'Red')}</row></sheetData>${x14}`) },
        { name: 'Lists', xml: worksheetXml(`<sheetData><row r="1">${str('A1', 'Red')}</row><row r="2">${str('A2', 'Blue')}</row></sheetData>`) },
      ],
    });
    await mount(page, bytes, { author: 'Test' });
    await view(page, 'view.setComment(1, 1, "A note")');
    await select(page, 'B2');
    const clip = await clipboardEvent(page, 'copy');
    // The notes of the other sheet cannot be changed (as the reader says of a sheet whose comment parts are shared).
    await view(page, 'void (view.workbook.sheets[1].notesBlocked = "shared")');
    await view(page, 'view.setActiveSheet(1)');
    await select(page, 'C4');
    await clipboardEvent(page, 'paste', clip);
    expect(await cellValue(page, 'C4')).toBe('Red');
    await expect
      .poll(() => notices(page))
      .toEqual(['One note was not pasted: its cell cannot take a note; One data validation or conditional format could not be pasted as it is where the cells come from: it is of a kind that is kept as the file has it']);
  });

  test('a read-only view copies and changes nothing: no cut, no paste, no rule moved', async ({ page }) => {
    await mount(page, await workbook(), { readOnly: true });
    await select(page, 'A2');
    const clip = await clipboardEvent(page, 'cut');
    expect(clip.text).toBe('3');
    expect(await cellValue(page, 'A2')).toBe(3);
    expect(await ruleAt(page, 'A2')).toBe('A2:A9|whole|1|10');
    await select(page, 'C4');
    await clipboardEvent(page, 'paste', clip);
    expect(await cellValue(page, 'C4')).toBeNull();
    expect(await ruleAt(page, 'C4')).toBeNull();
    expect(await formats(page)).toEqual(['A2:A9|cellIs|B2']);
    expect(await changes(page)).toBe(0);
  });
});
